# Parse tau value, model, benchmark, seed from exp_id and spec
import re

def parse_tau_exp(eid, e):
    spec = e.get('spec', {})
    cmd = spec.get('command', '') if isinstance(spec, dict) else ''

    # Extract tau value
    tau_match = re.search(r'tau[_-]?0*(\d+)', eid)
    tau_val = None
    if tau_match:
        digits = tau_match.group(1)
        # e.g., tau015 -> 0.15, tau050 -> 0.50, tau005 -> 0.05
        if len(digits) == 2:
            tau_val = float(f"0.{digits}")
        elif len(digits) == 3:
            tau_val = float(f"0.{digits}")
        elif len(digits) == 1:
            tau_val = float(f"0.{digits}")
    # Also try from command line
    if tau_val is None:
        tau_cmd = re.search(r'--tau[= ]+([0-9.]+)', cmd)
        if tau_cmd:
            tau_val = float(tau_cmd.group(1))

    # Extract model
    model = 'smolvla'
    if 'pi05' in eid or 'pi0.5' in eid:
        model = 'pi05'
    elif '--model pi' in cmd or 'pi0' in cmd:
        model = 'pi05'

    # Extract benchmark
    benchmark = None
    for b in ['goal', 'long', 'spatial', 'object']:
        if b in eid:
            benchmark = b
            break
    if benchmark is None:
        bm_match = re.search(r'--benchmark[= ]+(\w+)', cmd)
        if bm_match:
            benchmark = bm_match.group(1)

    # Extract seed
    seed_match = re.search(r's(\d+)', eid)
    seed = int(seed_match.group(1)) if seed_match else None
    if seed is None:
        seed_cmd = re.search(r'--seed[= ]+(\d+)', cmd)
        if seed_cmd:
            seed = int(seed_cmd.group(1))

    return {
        'exp_id': eid,
        'model': model,
        'benchmark': benchmark,
        'tau': tau_val,
        'seed': seed,
        'sr': e.get('sr'),
        'trigger_rate': e.get('trigger_rate'),
        'conclusion': e.get('conclusion')
    }

parsed_tau = [parse_tau_exp(eid, e) for eid, e in tau_exps.items()]
# Filter those with valid SR
valid_tau = [p for p in parsed_tau if p['sr'] is not None]
no_sr_tau = [p for p in parsed_tau if p['sr'] is None]

print(f"With valid SR: {len(valid_tau)}, without SR: {len(no_sr_tau)}")

