            seen[dk] = it
    deduped_groups[key] = sorted(seen.values(), key=lambda x: (x['tau'] or 0, x['seed'] or 0))

for key in sorted(deduped_groups.keys()):
    items = deduped_groups[key]
    print(f"\n### {key} ({len(items)} data points)")
    for it in items:
        tr_str = f"{it['trigger_rate']}" if it['trigger_rate'] is not None else '—'
